files.scripts/api.vela:
/* 中😀 */
pub fn pick(source_value: i64, reason: String = "base") -> bool { return true; }
fn hidden(private_value: i64) -> bool { return true; }
pub fn zero() -> bool { return true; }
pub const token: i64 = 1;
pub state stored: i64 = 1;
pub struct Row { value: i64 }
impl Row { pub fn pick(self, source_method: i64, reason: String = "base") -> bool { return true; } }
pub trait Readable { fn read(self, source_trait: i64, reason: String = "base") -> bool { return true; } }
impl Readable for Row {}
pub enum Choice { Pair(arg0: i64, arg1: String), Empty, Named { value: i64 } }
pub fn current() -> Row { return Row { value: 1 }; }
pub fn opaque() -> Any { return Row { value: 1 }; }
pub async fn worker() -> i64 { return 1; }
pub fn done(result: Result<i64, task::Error>) {}

